/**
 * Словари локализации — единственный источник всех UI-строк сайта.
 * ru — русский (дефолт), os — осетинский (иронский диалект, кириллица с ӕ/æ).
 *
 * Контент из Payload (объекты, статьи, агенты, тексты «О нас») сюда НЕ входит —
 * он остаётся как введён в админке (на русском).
 *
 * os типизирован как typeof ru: если в осетинском словаре пропущен ключ,
 * сборка не пройдёт. Это гарантирует полноту перевода.
 */

export const locales = ['ru', 'os'] as const
export type Locale = (typeof locales)[number]
export const defaultLocale: Locale = 'ru'

export function isLocale(v: string): v is Locale {
  return (locales as readonly string[]).includes(v)
}

