  // Страницы «Ипотека и выгодные условия» (/mortgage) и «Рассрочка»
  // (/installment): программы покупки, калькулятор платежа, банки, шаги
  // сделки, частые вопросы и форма заявки (см. PurchaseLeadForm). Это не
  // услуги раздела «Услуги» (services.mortgage, services.broker): там про
  // сопровождение сделки, здесь — про сами программы покупки.
  //
  // Формулировки без обещаний: «одобрение за 1 день», «гарантированное
  // одобрение», конкретные ставки без подтверждения банка и «без процентов»
