        title: '9. Архайдты истори сайты',
        text: 'Цæмæн базонам, посетителтæн цы объекттæ интерес кæнынц, уый тыххæй сайт кæны йæ хион æнæперсоналон статистикæ: фарсы адрес, визиты рæстæг, уæлдæфон тип, раивдæн æрбацæуæн, байгомгонд объекты карточкæтæ, каталогы равзæрст филтртæ, избранноемæ бафтау æмæ тыхс «Позвонить», WhatsApp кæнæ «Написать». Cookie-тæ уымæн нæ пайдагæнынц, IP-адрес нæ хæдзардзыд цæуы: уымæй æмæ браузеры бæрæггæнæнтæй серверыл нымад цæуы æнæрафыссынæн хеш, йæ соль алы мæй ивы — ахæм хешæй адæймаджы базонæн нæй. Регион райсынц æрмæст прокси кæнæ CDN-ы сæргæй, кæд уый сæ арвиты. Кæд уæхæдæг формæ арвыстат, уæ архайдты истори баст цæуы обращениемæ — агент заявкæйы карточкæйы уыны блок «Активность на сайте» (фæстаг визит, цал хатты æрбацыд, цы объекттæ федта), цæмæн ма бафарса уæ ногæй. Ном, телефон æмæ почтæ статистикæйы нæ вæййынц: уыдон ис æрмæст заявкæйы. Æмбæхст деанонимизаци нæй — сайт IP-йæ адæймаг нæ равзары æмæ æртыккаг æрдæгтæй бæрæггæнæнтæ нæ ауæй кæны. Статистикæ æвæрынц 400 боны, бацæуæн æй ис æрмæст администраторæн, æмæ алы отчеты фенын ныффыссынц бацæуæны журналмæ.',
